// Not measurable here (CCharacterSet, FmtStr, CDAPacket): the string "present", or null
// for a null pointer. make_oracle_iclient.py emits these by name, not through an overload.
void OracleArgPresence(FOracleJson& J, char const* Name, bool bPresent);

// Arrays the signature sizes with a separate count argument.
void OracleArgUintArray(FOracleJson& J, char const* Name, unsigned int const* Values, int Count);

// The common head of an IClient record: {"frame","seq","slot","m","a":{...}}. Begin opens
// "a" and returns the call's seq; End closes it and writes the line to iclient.jsonl. Seq
// numbers count calls in entry order. A record is written before the call is forwarded, so
// a call the real client makes back into the proxy while it handles one comes after it.
unsigned OracleIClientBegin(FOracleJson& J, int Slot, char const* Method);
void OracleIClientEnd(FOracleJson& J);
// A non-void slot's answer, written after the call returned:
// {"frame","seq","slot","m","r": <value>}. Begin writes the head; the caller adds "r";
// End writes the line.
void OracleIClientReturnBegin(FOracleJson& J, int Slot, char const* Method, unsigned Seq);
void OracleIClientReturnEnd(FOracleJson& J);
